// The documented workaround for kernels generated by `macro_rules!`: let the
// declarative macro emit the whole `#[cuda_module] mod`. By the time the
// attribute runs, the repetition has been expanded into ordinary `#[kernel]`
// functions, so every generated kernel gets a launcher.

use cuda_core::CudaStream;
use cuda_core::LaunchConfig;
use cuda_macros::cuda_module;

macro_rules! fill_module {
    ($($name:ident: $ty:ty),* $(,)?) => {
        #[cuda_module]
        mod kernels {
            $(
                #[cuda_macros::kernel]
                pub fn $name(value: $ty) {
                    let _ = value;
                }
            )*
        }
    };
}

fill_module!(fill_u32: u32, fill_u64: u64);

fn typecheck_generated(module: &kernels::LoadedModule, stream: &CudaStream, config: LaunchConfig) {
    // SAFETY: this compile-pass fixture supplies the raw launch proofs.
    unsafe {
        let _ = module.fill_u32(stream, config, 7u32);
        let _ = module.fill_u64(stream, config, 7u64);
    }
}

fn main() {
    let _ = typecheck_generated;
}
